require "test_helper"

# The Solid Queue MCP tools are admin only (generated by maquina:solid_queue):
# only someone on the backstage list sees them. A member's token must not learn
# they exist: they are absent from tools/list and a call gets the same -32602
# as an unknown tool. McpTestHelper turns any MCP feature flag on and puts
# mcp_admin on the backstage list, so access is the only gate tested.
class Mcp::Tools::SolidQueueTest < ActionDispatch::IntegrationTest
  TOOLS = Mcp::Tools::SolidQueue::DEFINITIONS.map { |definition| definition[:name] }
  ARGUMENTS = {"get_failed_job" => {id: 0}, "retry_failed_job" => {id: 0}, "discard_failed_job" => {id: 0}}.freeze

  test "an admin sees the tools" do
    assert_equal TOOLS, TOOLS & listed_tools(users(:mcp_admin))
  end

  test "a member does not see the tools" do
    assert_empty TOOLS & listed_tools(users(:mcp_member))
  end

  test "a member calling any of the tools gets unknown tool" do
    token = oauth_token_for(users(:mcp_member), scope: "read write")

    TOOLS.each do |name|
      mcp_post({jsonrpc: "2.0", id: 1, method: "tools/call", params: {name: name, arguments: ARGUMENTS.fetch(name, {})}}, token: token)

      assert_equal(-32602, response.parsed_body.dig("error", "code"), name)
    end
  end

  test "queue_status counts the failed job in its queue" do
    create_failed_job(queue: "billing")

    billing = call_tool("queue_status")["queues"].find { |queue| queue["name"] == "billing" }

    assert_equal 1, billing["failed"]
    assert_equal 0, billing["ready"]
  end

  test "list_failed_jobs and get_failed_job describe the failure with arguments redacted" do
    job = create_failed_job

    listed = call_tool("list_failed_jobs")["failed_jobs"]
    assert_equal [job.id], listed.map { |failed| failed["id"] }
    assert_equal "ArgumentError", listed.first["exception_class"]

    detail = call_tool("get_failed_job", {id: job.id})
    assert_equal "ChargeJob", detail["job_class"]
    assert_equal [{"amount" => 10, "card_number" => "[REDACTED]"}], detail["arguments"]
    assert_predicate detail["backtrace"], :any?
  end

  test "retry_failed_job puts the job back on its queue" do
    skip "Read-only tools: rails g maquina:solid_queue --mcp-write adds retry_failed_job" unless TOOLS.include?("retry_failed_job")
    job = create_failed_job

    assert call_tool("retry_failed_job", {id: job.id}, scope: "read write")["retried"]
    assert_not SolidQueue::FailedExecution.exists?(job_id: job.id)
    assert SolidQueue::ReadyExecution.exists?(job_id: job.id)
  end

  test "discard_failed_job deletes the job and its failure" do
    skip "Read-only tools: rails g maquina:solid_queue --mcp-write adds discard_failed_job" unless TOOLS.include?("discard_failed_job")
    job = create_failed_job

    assert call_tool("discard_failed_job", {id: job.id}, scope: "read write")["discarded"]
    assert_not SolidQueue::Job.exists?(job.id)
    assert_not SolidQueue::FailedExecution.exists?(job_id: job.id)
  end

  private

  def listed_tools(user)
    mcp_post({jsonrpc: "2.0", id: 1, method: "tools/list", params: {}}, token: oauth_token_for(user, scope: "read write"))
    response.parsed_body.dig("result", "tools").map { |tool| tool["name"] }
  end

  def call_tool(name, arguments = {}, scope: "read")
    mcp_post({method: "tools/call", params: {name: name, arguments: arguments}}, token: oauth_token_for(users(:mcp_admin), scope: scope))
    assert_response :success
    result = response.parsed_body["result"]
    assert_equal false, result["isError"], result.dig("content", 0, "text")
    result["structuredContent"]
  end

  # A job as Solid Queue leaves it after its last attempt raised: no ready
  # execution, one failed execution holding the exception.
  def create_failed_job(queue: "default")
    job = SolidQueue::Job.create!(queue_name: queue, class_name: "ChargeJob", active_job_id: SecureRandom.uuid,
      arguments: {"job_class" => "ChargeJob", "executions" => 1, "arguments" => [{"amount" => 10, "card_number" => "4242"}]})
    job.ready_execution&.destroy!

    begin
      raise ArgumentError, "card declined"
    rescue => error
      SolidQueue::FailedExecution.create!(job: job, exception: error)
    end
    job
  end
end
